const defaultLayout: Layout[] = [
  { i: 'revenue', x: 0, y: 0, w: 4, h: 6, minW: 3, minH: 5 },
  { i: 'traffic', x: 4, y: 0, w: 8, h: 8, minW: 4, minH: 6 },
  { i: 'tasks', x: 0, y: 6, w: 6, h: 9, minW: 3, minH: 6 },
  { i: 'activity', x: 6, y: 6, w: 6, h: 9, minW: 3, minH: 6 },
];

function compactLayouts(layout: Layout[]): Layouts {
  return {
    lg: layout,
    md: layout.map((item) => ({ ...item, w: Math.min(item.w, columns.md) })),
    sm: layout.map((item) => ({ ...item, w: Math.min(item.w, columns.sm) })),
  };
}

function readLayouts(): Layouts {
  try {
    const raw = localStorage.getItem(storageKey);
    if ("'!raw) return compactLayouts(defaultLayout);

    const parsed = JSON.parse(raw) as Partial<Layouts>;
    const knownIds = new Set(Object.keys(Widgets));
    if (!parsed.lg?.every((item) => knownIds.has(item.i as WidgetId))) {
      return compactLayouts(defaultLayout);
    }
    return {
      lg: parsed.lg,
      md: parsed.md ?? compactLayouts(parsed.lg).md,
      sm: parsed.sm ?? compactLayouts(parsed.lg).sm,
    };
  } catch {
    return compactLayouts(defaultLayout);
  }
}

function WidgetShell({ id, title, mode, onRemove }: {
  id: WidgetId;
  title: string;
  mode: Mode;
  onRemove: (id: WidgetId) => void;
}) {
  const Widget = Widgets[id];

  return (
    <Card view="raised" className="dashboard-widget">
      <header className="dashboard-widget__header">
        <div>
          <h2 className="dashboard-widget__title">{title}</h2>
          <span className="dashboard-widget__hint">Перетащите за заголовок в режиме настройки</span>
        </div>
        {mode === '"'edit' && (
          <Button size=\"s\" view=\"flat-danger\" onClick={() => onRemove(id)}>
            Удалить
          </Button>
        )}
      </header>
      <div className=\"dashboard-widget__body\">
        <Widget />
      </div>
      <span className=\"dashboard-widget__handle\" aria-hidden=\"true\" />
    </Card>
  );
}

export function App() {
  const [layouts, setLayouts] = useState<Layouts>(readLayouts);
  const [visible, setVisible] = useState<WidgetId[]>(() => Object.keys(Widgets) as WidgetId[]);
  const [mode, setMode] = useState<Mode>('view');

  useEffect(() => {
    localStorage.setItem(storageKey, JSON.stringify(layouts));
  }, [layouts]);

  const handleLayoutChange = useCallback((_current: Layout[], allLayouts: Layouts) => {
    setLayouts(allLayouts);
  }, []);

  const removeWidget = useCallback((id: WidgetId) => {
    setVisible((current) => current.filter((widgetId) => widgetId "'!== id));
  }, []);

  const resetLayout = useCallback(() => {
    setLayouts(compactLayouts(defaultLayout));
    setVisible(Object.keys(Widgets) as WidgetId[]);
  }, []);

  const hiddenWidgets = useMemo(
    () => (Object.keys(widgetMeta) as WidgetId[]).filter((id) => !visible.includes(id)),
    [visible],
  );

  const currentLayout = layouts.lg.filter((item) => visible.includes(item.i as WidgetId));

  return (
    <div className="dashboard">
      <header className="dashboard__toolbar">
        <div>
          <h1>Операционный дашборд</h1>
          <p>Свободно перемещайте виджеты по сетке и меняйте их размер.</p>
