        cols={columns}
        rowHeight={28}
        margin={[16, 16]}
        containerPadding={[0, 0]}
        isDraggable={mode === 'edit'}
        isResizable={mode === 'edit'}
        draggableHandle=\".dashboard-widget__header\"
        onLayoutChange={handleLayoutChange}
      >
        {visible.map((id) => (
          <div key={id}>
            <WidgetShell
              id={id}
              title={widgetMeta[id].title}
              mode={mode}
              onRemove={removeWidget}
            />
          </div>
        ))}
      </ResponsiveGrid>
    </div>
