}

.dashboard__grid--edit .dashboard-widget__handle {
  opacity: 1;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 6px;
  height: 100%;
  justify-content: center;
}

.metric strong {
  font-size: clamp(26px, 5cqw, 44px);
  line-height: 1;
  color: var(--g-color-text-primary);
}

.metric span,
.metric em,
.compact-list small {
  color: var(--g-color-text-secondary);
}

.metric em {
  font-style: normal;
  font-size: 14px;
}

.metric--warning strong {
  color: var(--g-color-text-danger);
}

.metric--positive strong {
  color: var(--g-color-text-positive);
}

.sparkline {
  width: 100%;
  height: calc(100% - 8px);
}

.compact-list {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
