const ResponsiveGrid = WidthProvider(Responsive);

type WidgetId = keyof typeof Widgets;
type Layouts = Record<string, Layout[]>;
type Mode = 'view' | 'edit';

import { dashboardStorageKey as storageKey } from './dashboard-utils';

const defaultLayout: Layout[] = [
  { i: 'revenue', x: 0, y: 0, w: 4, h: 6, minW: 3, minH: 5 },
  { i: 'traffic', x: 4, y: 0, w: 8, h: 8, minW: 4, minH: 6 },
  { i: 'tasks', x: 0, y: 6, w: 6, h: 9, minW: 3, minH: 6 },
  { i: 'activity', x: 6, y: 6, w: 6, h: 9, minW: 3, minH: 6 },
];

function compactLayouts(layout: Layout[]): Layouts {
  return {
    lg: layout,
    md: layout.map((item) => ({ ...item, w: Math.min(item.w, columns.md) })),
    sm: layout.map((item) => ({ ...item, w: Math.min(item.w, columns.sm) })),
  };
}

function readLayouts(): Layouts {
  try {
    const raw = localStorage.getItem(storageKey);
    if (!raw) return compactLayouts(defaultLayout);

    const parsed = JSON.parse(raw) as Partial<Layouts>;
    const knownIds = new Set(Object.keys(Widgets));
    if (!parsed.lg?.every((item) => knownIds.has(item.i as WidgetId))) {
      return compactLayouts(defaultLayout);
    }
    return {
      lg: parsed.lg,
      md: parsed.md ?? compactLayouts(parsed.lg).md,
      sm: parsed.sm ?? compactLayouts(parsed.lg).sm,
    };
  } catch {
    return compactLayouts(defaultLayout);
  }
}

